import React, { useState } from 'react';
import '../styles/theme.css';

export default function NewSale() {
  const [formData, setFormData] = useState({
    party: 'ABC Foods Pvt. Ltd.',
    commodity: 'Wheat',
    grade: 'FAQ',
    weight: '125',
    rate: '2650',
    freight: '10500',
    received: ''
  });

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const weight = Number(formData.weight) || 0;
  const rate = Number(formData.rate) || 0;
  const freight = Number(formData.freight) || 0;

  // Sale Amount = Weight (Qtl) * Rate
  const saleAmount = (weight * rate).toFixed(2);
  
  // Final Sale Amount = Sale Amount + Freight & Deductions
  const finalSaleAmount = (Number(saleAmount) + freight).toFixed(2);

  return (
    <div style={{ padding: '20px', maxWidth: '480px', margin: '0 auto', fontFamily: 'Segoe UI, sans-serif' }}>
      
      {/* Header */}
      <div style={{ fontSize: '12px', color: '#666', marginBottom: '2px' }}>New entry</div>
      <h2 style={{ color: '#1B4D3E', marginTop: 0, marginBottom: '20px' }}>New Sale</h2>

      <form style={{ display: 'flex', flexDirection: 'column', gap: '15px' }}>
        
        {/* Company / Party */}
        <div>
          <label style={labelStyle}>Company / Party</label>
          <input type="text" name="party" value={formData.party} onChange={handleChange} style={inputStyle} />
        </div>

        {/* Commodity & Grade Grid */}
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '12px' }}>
          <div>
            <label style={labelStyle}>Commodity</label>
            <input type="text" name="commodity" value={formData.commodity} onChange={handleChange} style={inputStyle} />
          </div>
          <div>
            <label style={labelStyle}>Grade</label>
            <input type="text" name="grade" value={formData.grade} onChange={handleChange} style={inputStyle} />
          </div>
        </div>

        {/* Weight & Rate Grid */}
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '12px' }}>
          <div>
            <label style={labelStyle}>Weight (Qtl)</label>
            <input type="number" name="weight" value={formData.weight} onChange={handleChange} style={inputStyle} />
          </div>
          <div>
            <label style={labelStyle}>Rate / Qtl</label>
            <input type="number" name="rate" value={formData.rate} onChange={handleChange} style={inputStyle} />
          </div>
        </div>

        {/* Freight & Deductions */}
        <div>
          <label style={labelStyle}>Freight & deductions</label>
          <input type="number" name="freight" value={formData.freight} onChange={handleChange} style={inputStyle} />
        </div>

      </form>

      {/* Summary Box */}
      <div style={{ background: '#F4F1EA', padding: '16px', borderRadius: '12px', marginTop: '20px', border: '1px solid #EAE5D9' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '10px', fontSize: '14px', color: '#555' }}>
          <span>Sale amount</span>
          <span style={{ fontWeight: 'bold', color: '#333' }}>₹ {Number(saleAmount).toLocaleString('en-IN')}</span>
        </div>
        <hr style={{ border: 'none', borderTop: '1px solid #E2DCD0', margin: '10px 0' }} />
        <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: '15px' }}>
          <span style={{ fontWeight: 'bold', color: '#1B4D3E' }}>Final sale amount</span>
          <span style={{ fontWeight: 'bold', color: '#1B4D3E', fontSize: '18px' }}>₹ {Number(finalSaleAmount).toLocaleString('en-IN')}</span>
        </div>
      </div>

      {/* Amount Received */}
      <div style={{ marginTop: '20px' }}>
        <label style={labelStyle}>Amount received</label>
        <input type="number" name="received" placeholder="Enter amount" value={formData.received} onChange={handleChange} style={inputStyle} />
      </div>

      {/* Submit Button */}
      <button style={{ width: '100%', background: '#1B4D3E', color: '#FFF', padding: '14px', border: 'none', borderRadius: '12px', fontWeight: 'bold', fontSize: '16px', marginTop: '25px', cursor: 'pointer', boxShadow: '0 4px 10px rgba(0,0,0,0.1)' }}>
        Generate Invoice
      </button>

    </div>
  );
}

const labelStyle = { display: 'block', fontSize: '12px', fontWeight: '600', color: '#555', marginBottom: '6px' };
const inputStyle = { width: '100%', padding: '12px', borderRadius: '10px', border: '1px solid #EAE5D9', background: '#FFF', fontSize: '14px', boxSizing: 'border-box' };
